CREATE DATABASE IF NOT EXISTS qr_absensi CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE qr_absensi;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS pengajuan_absensi, absensi, sesi_absensi, kelas_mahasiswa, jadwal, lokasi_kampus, users, mahasiswa, dosen, mata_kuliah, kelas;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','dosen','mahasiswa') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE kelas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama_kelas VARCHAR(50) NOT NULL,prodi VARCHAR(150) NOT NULL,angkatan YEAR NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_kelas(nama_kelas,prodi,angkatan)) ENGINE=InnoDB;
CREATE TABLE dosen(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nidn VARCHAR(30) UNIQUE NOT NULL,nama VARCHAR(150) NOT NULL,email VARCHAR(150),no_hp VARCHAR(30),foto VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE mata_kuliah(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kode_mk VARCHAR(30) UNIQUE NOT NULL,nama_mk VARCHAR(150) NOT NULL,sks TINYINT UNSIGNED DEFAULT 3,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE mahasiswa(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,npm VARCHAR(30) UNIQUE NOT NULL,nama VARCHAR(150) NOT NULL,foto VARCHAR(255),tempat_lahir VARCHAR(100),tanggal_lahir DATE,jenis_kelamin ENUM('Laki-laki','Perempuan'),fakultas VARCHAR(150),prodi VARCHAR(150),angkatan YEAR,kelas_id INT UNSIGNED NULL,no_hp VARCHAR(30),email VARCHAR(150),alamat TEXT,kabupaten_kota VARCHAR(100),provinsi VARCHAR(100),qr_code VARCHAR(120) UNIQUE NOT NULL,face_verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(kelas_id) REFERENCES kelas(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE kelas_mahasiswa(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kelas_id INT UNSIGNED NOT NULL,mahasiswa_id INT UNSIGNED NOT NULL,UNIQUE KEY uq_km(kelas_id,mahasiswa_id),FOREIGN KEY(kelas_id) REFERENCES kelas(id) ON DELETE CASCADE,FOREIGN KEY(mahasiswa_id) REFERENCES mahasiswa(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE jadwal(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mata_kuliah_id INT UNSIGNED NOT NULL,dosen_id INT UNSIGNED NOT NULL,kelas_id INT UNSIGNED NOT NULL,hari ENUM('Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu') NOT NULL,jam_mulai TIME NOT NULL,jam_selesai TIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(mata_kuliah_id) REFERENCES mata_kuliah(id) ON DELETE CASCADE,FOREIGN KEY(dosen_id) REFERENCES dosen(id) ON DELETE CASCADE,FOREIGN KEY(kelas_id) REFERENCES kelas(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE lokasi_kampus(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama_lokasi VARCHAR(100) NOT NULL,latitude DECIMAL(10,8) NOT NULL,longitude DECIMAL(11,8) NOT NULL,radius INT UNSIGNED NOT NULL DEFAULT 100,status ENUM('Aktif','Nonaktif') NOT NULL DEFAULT 'Aktif',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE sesi_absensi(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,jadwal_id INT UNSIGNED NOT NULL,pertemuan INT UNSIGNED NOT NULL,tanggal DATE NOT NULL,jam_mulai TIME NOT NULL,jam_selesai TIME NOT NULL,token VARCHAR(120) UNIQUE NOT NULL,status ENUM('aktif','selesai','dibatalkan') DEFAULT 'aktif',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(jadwal_id) REFERENCES jadwal(id) ON DELETE CASCADE,UNIQUE KEY uq_sesi(jadwal_id,tanggal)) ENGINE=InnoDB;
CREATE TABLE absensi(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sesi_id INT UNSIGNED NOT NULL,mahasiswa_id INT UNSIGNED NOT NULL,status ENUM('Hadir','Terlambat','Izin','Sakit','Tidak Hadir') NOT NULL,waktu_absen DATETIME NULL,latitude DECIMAL(10,8),longitude DECIMAL(11,8),jarak DECIMAL(10,2),lokasi_id INT UNSIGNED NULL,keterangan TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_absen(sesi_id,mahasiswa_id),FOREIGN KEY(sesi_id) REFERENCES sesi_absensi(id) ON DELETE CASCADE,FOREIGN KEY(mahasiswa_id) REFERENCES mahasiswa(id) ON DELETE CASCADE,FOREIGN KEY(lokasi_id) REFERENCES lokasi_kampus(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE pengajuan_absensi(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sesi_id INT UNSIGNED NOT NULL,absensi_id INT UNSIGNED NULL,mahasiswa_id INT UNSIGNED NOT NULL,jenis ENUM('Izin','Sakit') NOT NULL,alasan TEXT NOT NULL,bukti VARCHAR(255),status ENUM('Menunggu','Disetujui','Ditolak') DEFAULT 'Menunggu',catatan_dosen TEXT,diverifikasi_oleh INT UNSIGNED NULL,diverifikasi_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sesi_id) REFERENCES sesi_absensi(id) ON DELETE CASCADE,FOREIGN KEY(absensi_id) REFERENCES absensi(id) ON DELETE SET NULL,FOREIGN KEY(mahasiswa_id) REFERENCES mahasiswa(id) ON DELETE CASCADE,FOREIGN KEY(diverifikasi_oleh) REFERENCES dosen(id) ON DELETE SET NULL) ENGINE=InnoDB;
-- Setelah import, login mahasiswa menggunakan NPM dan password 123456.
